-- Emergency maintenance-window inverse ONLY. Requires the expected-state preamble
-- generated by mnt-prepare-rollback.mjs in this same database session.
-- No rows, objects, buckets or history are deleted. MNT content stays MNT.
begin;
select pg_advisory_xact_lock(781023);
lock table public.mnt_records,public.mnt_staff,public.mnt_record_references,
  public.mnt_rate_limits,public.mnt_record_revisions in access exclusive mode;
lock table storage.objects in share mode;

do $guard$
declare item record; actual_hash text; actual_count bigint; ordering text;
begin
  if to_regclass('pg_temp.mnt_expected_cutover_state') is null then
    raise exception 'Rollback refused: verified expected-state preamble required';
  end if;
  if (select count(*) from pg_temp.mnt_expected_cutover_state)<>5 then
    raise exception 'Rollback refused: all five table checksums required';
  end if;
  for item in select * from pg_temp.mnt_expected_cutover_state loop
    if item.suffix not in ('staff','records','record_references','rate_limits','record_revisions') then
      raise exception 'Rollback refused: unknown expected table';
    end if;
    ordering := case item.suffix when 'staff' then 'user_id' when 'rate_limits' then 'key'
      when 'record_references' then 'source_collection,source_id,field' else 'collection,id' end;
    execute format('select count(*),md5(coalesce(jsonb_agg(%s order by %s),''[]''::jsonb)::text) from public.%I t',
      case when item.suffix='records' then 'to_jsonb(t)-''updated_at''' else 'to_jsonb(t)' end,
      ordering,'mnt_'||item.suffix) into actual_count,actual_hash;
    if actual_count<>item.row_count or actual_hash<>item.checksum then
      raise exception 'Rollback refused: state changed after cutover (%)',item.suffix;
    end if;
  end loop;
  if exists(select 1 from storage.objects where bucket_id like 'mnt-%') then
    raise exception 'Rollback refused: MNT storage objects require an explicit compatible recovery plan';
  end if;
end;
$guard$;

do $inverse$
declare item record; new_name text;
begin
  for item in select relname from pg_class where relnamespace='public'::regnamespace
    and relkind='r' and relname in ('mnt_staff','mnt_records','mnt_record_references','mnt_rate_limits','mnt_record_revisions') loop
    execute format('alter table public.%I rename to %I',item.relname,replace(item.relname,'mnt_','cota_'));
  end loop;
  for item in select c.conname,t.relname from pg_constraint c join pg_class t on t.oid=c.conrelid
    where t.relnamespace='public'::regnamespace and c.conname like 'mnt\_%' escape '\' loop
    execute format('alter table public.%I rename constraint %I to %I',item.relname,item.conname,replace(item.conname,'mnt_','cota_'));
  end loop;
  for item in select relname from pg_class where relnamespace='public'::regnamespace and relkind='i' and relname like 'mnt\_%' escape '\' loop
    execute format('alter index public.%I rename to %I',item.relname,replace(item.relname,'mnt_','cota_'));
  end loop;
  for item in select oid,proname from pg_proc where pronamespace='public'::regnamespace and proname like 'mnt\_%' escape '\' loop
    new_name:=replace(item.proname,'mnt_','cota_');
    execute format('alter function %s rename to %I',item.oid::regprocedure,new_name);
    execute replace(replace(pg_get_functiondef(item.oid),'mnt_','cota_'),'mnt-','cota-');
  end loop;
  for item in select schemaname,tablename,policyname from pg_policies where schemaname in ('public','storage') and policyname like 'mnt\_%' escape '\' loop
    execute format('alter policy %I on %I.%I rename to %I',item.policyname,item.schemaname,item.tablename,replace(item.policyname,'mnt_','cota_'));
  end loop;
  for item in select t.tgname,c.relname from pg_trigger t join pg_class c on c.oid=t.tgrelid
    where c.relnamespace='public'::regnamespace and not t.tgisinternal and t.tgname like 'mnt\_%' escape '\' loop
    execute format('alter trigger %I on public.%I rename to %I',item.tgname,item.relname,replace(item.tgname,'mnt_','cota_'));
  end loop;
end;
$inverse$;

-- Both generations stay private even though compatibility names are restored.
create or replace function public.cota_public_url(u text) returns boolean
language sql immutable set search_path = '' as $$
  select coalesce(u ~ '^(https?://[^/[:space:]]+|/[^/])' and u !~ '[[:cntrl:]]'
    and u !~* '((cota|mnt)-(private|staging)|/api/admin/|/storage/v1/object/sign/)',false);
$$;
alter policy cota_storage_read on storage.objects to authenticated
  using (bucket_id in ('cota-private','cota-public') and (select public.cota_is_staff()));
drop table pg_temp.mnt_expected_cutover_state;
notify pgrst,'reload schema';
commit;
